window.jQuery||document.writeln('<script src = "static/jquery-3.5.1.min.js">');var buttonColors=["red","blue","green","yellow"];var level=1;var generatedSequence=[];var userSeqIndx=0;var hasGameEnded=true;var winningTexts=["Keep going! 🎉","Amazing!🔥","Champion vibes! 🏆","Incredible!🌟","You're unstoppable! 🚀","Fantastic! 💫","Great job! 👏","Superb! 🌈","You're a star! ⭐","Outstanding! 🥇","Bravo! 🎊","Legendary! 🐾"];var wrongAudio=new Audio("./sounds/wrong.mp3");var winningTextIndex=0;function cycleQuotes(){if(++winningTextIndex+1>winningTexts.length){winningTextIndex=0}return winningTexts[winningTextIndex]}function addNewColor(){generatedSequence.push(buttonColors[randomNumber()])}function randomNumber(){var random=parseInt(Math.random()*4);if(random>=4){randomException()}function randomException(){random=parseInt(Math.random()*4);if(random>=4){randomException()}}return random}async function animateSequence(){if(!hasGameEnded){for(var i=0;i<generatedSequence.length;i++){playAudio(generatedSequence[i]);await $("#"+generatedSequence[i]).animate({opacity:.3}).animate({opacity:1}).promise()}}}async function levelHandler(){if(!hasGameEnded){addNewColor();await animateSequence();checkSequence()}}async function checkSequence(){$(document).off("click");$(".btn").on("click",(function(event){if(!hasGameEnded){var button=$(this);playAudio(this.id);animatePressed(button);gameLogic(this.id);return}}))}function gameLogic(buttonId){if(userSeqIndx+1==generatedSequence.length){if(buttonId!=generatedSequence[userSeqIndx++]){gameLost();return false}setTimeout((function(){nextLevel()}),1e3);return true}else if(userSeqIndx<generatedSequence.length){if(buttonId!=generatedSequence[userSeqIndx++]){gameLost();return false}}else{gameLost();return false}}function playAudio(name){var audio=new Audio(`./sounds/${name}.mp3`);audio.play().then((function(){audio.remove()}))}function animatePressed(button){button.addClass("pressed");button.animate({opacity:.3}).animate({opacity:1}).promise();setTimeout((function(){button.removeClass("pressed")}),200)}function gameLost(){$("#level-title").text("Aw cutie, you lost! Wanna marry me?💐 Press A.");wrongAudio.play();$("body").addClass("game-over");setTimeout((function(){$("body").removeClass("game-over");$(document).on("click",startGame)}),200);$(".btn").off("click");hasGameEnded=true}function nextLevel(){$("#level-title").text(winningTexts[randomNumber()]);setTimeout((function(){$("#level-title").text("Level: "+ ++level)}),1e3);userSeqIndx=0;levelHandler();$(".btn").off("click")}function startGame(){if(hasGameEnded){level=1;generatedSequence=[];userSeqIndx=0;$("#level-title").text("Game On!");hasGameEnded=false;levelHandler()}}$(document).on("click",startGame);$(document).on("keydown",(function(event){if(event.key.toLowerCase()=="a"&&hasGameEnded){startGame()}}));